		}
	}
	if(/reply\/reply/.test(baseUrl) && !/pn=2/.test(baseUrl)){
		let c = Number(S("$.data.page.count"));	
		let size = Number(S("$.data.page.size"));
		page = Math.ceil(c/size);
		for(i = 2;i<=page;i++){
		  list.push(baseUrl.replace(/pn=\d+/,'pn='+i))
		}
		}
list

searchUrl:
@js:

let start = key.slice(0,1);
let type;
switch(start){
	case "@":
	    type = "bili_user";
	    break;
	case "#":
	case "＃":
	    type = "article"
	    break;
	case "%":
	    type = "video"
	    break
	case "&":
	    type = "live"
	    break;
	case "*":
	    type = "media_bangumi";
	    break;
	 case "?":
	 case "？":
	     type = "media_ft"
	     break
	}
if(type){
queryJson = {
        __refresh__: true,
        _extra: '',
        context: '',
        page: page,
        page_size: 30,
        order: '',
        duration: '',
        from_source: '',
        from_spmid: 333.337,
        platform: 'pc',
        highlight: 1,
        single_column: 0,
        keyword: key,
        search_type: type,
        preload: true,
        com2co: true
    }
    parms = getWbiEnc(queryJson);
    result = 'https://api.bilibili.com/x/web-interface/wbi/search/type?' + parms;

}else{
result = "https://api.bilibili.com/x/web-interface/wbi/search/all/v2?"+getWbiEnc({keyword:key,page: page,page_size: 30})
}

